-- ---- Brg_Reading ----
CREATE TABLE IF NOT EXISTS `Brg_Reading` (
  `_row_id` int unsigned NOT NULL AUTO_INCREMENT,
  `ID_Brg` int DEFAULT NULL,
  `Brg_Name` text DEFAULT NULL,
