CREATE TABLE IF NOT EXISTS `Dasa_Reading` (
  `_row_id` int unsigned NOT NULL AUTO_INCREMENT,
  `ID` int DEFAULT NULL,
  `DasaLord_E` varchar(255) DEFAULT NULL,
  `DasaPhal_E` text DEFAULT NULL,
  `DasaLord_H` varchar(255) DEFAULT NULL,
  `DasaPhal_H` text DEFAULT NULL,
  `DasaLord_P` varchar(255) DEFAULT NULL,
  `DasaPhal_P` text DEFAULT NULL,
  PRIMARY KEY (`_row_id`)
